# Run from RdistNN_stata. RdistNN is the authoritative reference, loaded from
# the live sibling source without rebuilding compiled code.
r_root <- normalizePath(file.path("..", "RdistNN"), mustWork = TRUE)
pkgload::load_all(r_root, compile = FALSE, quiet = TRUE)
lines <- c(
  "// Generated by tools/generate_r_clate_fixtures.R; do not hand edit.",
  paste0("// Reference RdistNN commit: ", system2("git", c("-C", shQuote(r_root), "rev-parse", "HEAD"), stdout = TRUE)),
  "// Binary-IV supplied nuisances, clipped propensity, paired frozen deletions."
)
emit <- function(name, value) {
  value <- as.matrix(value)
  rows <- apply(value, 1, function(z) paste(ifelse(is.na(z), ".", sprintf("%.17g", z)), collapse = ", "))
  lines <<- c(lines, sprintf("matrix R_cl_%s = (%s)", name, paste(rows, collapse = " \\ ")))
}
i <- seq_len(12)
X <- cbind(x1 = (i - 6) / 3, x2 = sin(i))
A <- as.integer(i %% 2 == 0)
D <- as.integer(i %% 3 != 0)
e <- c(.01, .99, seq(.2, .8, length.out = 10))
my0 <- .2 + X[, 1] / 3 - X[, 2] / 5
my1 <- my0 + 1 + X[, 2] / 4
md0 <- .15 + .02 * cos(i)
md1 <- .7 + .03 * sin(i)
Y <- my0 + D * (1 + X[, 2] / 4) + cos(i) / 5
X0 <- rbind(c(0, 0), c(-1, .5), c(1, -.4))
emit("input", cbind(X, Y, D, A, e, my0, my1, md0, md1))
emit("targets", X0)

cases <- data.frame(id = 1:4, method = c("exact", "exact", "asymp", "exact"),
  k = c(1L, 2L, 2L, 1L), distance = c("l2", "l2", "l2", "mahalanobis"))
for (case in seq_len(nrow(cases))) {
  f <- clate_dnn(X = X, X0 = X0, Y = Y, D = D, A = A, e = e,
    m_y0 = my0, m_y1 = my1, m_d0 = md0, m_d1 = md1, clip = .05,
    s = 4L, k = cases$k[case], method = cases$method[case],
    distance = cases$distance[case], return = c("W", "deletions", "dx", "signals"))
  d <- diagnostics(f)
  emit(paste0("theta", case), t(f$theta))
  emit(paste0("se", case), t(f$se))
  emit(paste0("components", case), f$components)
  emit(paste0("weights", case), f$W)
  emit(paste0("paired", case), t(vapply(f$component_vcov, function(v) c(v[1,1], v[1,2], v[2,2]), numeric(3))))
  # R reports marginal ratio covariance. Its retained paired deletions also
  # provide the joint target covariance used by Stata's e(V).
  G <- vapply(seq_len(nrow(X0)), function(j) {
    L <- sweep(f$deletions[, , j], 2L, colMeans(f$deletions[, , j]), "-")
    (L[, 1] - f$theta[j] * L[, 2]) / f$components[j, 2]
  }, numeric(nrow(X)))
  emit(paste0("vcov", case), (nrow(X)-1)/nrow(X)*crossprod(G))
  emit(paste0("diag", case), as.matrix(d[, c("n_eff", "max_weight", "top1_weight_share",
    "top5_weight_share", "top10_weight_share", "n_nonzero_weight", "radius_rank_k",
    "radius_rank_s", "weighted_mean_distance", "weighted_median_distance",
    "instrument_1_mass", "instrument_0_mass", "propensity_clipped_mass",
    "numerator_se", "denominator_se", "component_covariance", "component_correlation", "denominator_stat")]))
}
# A fixed direct-order grid exercises duplicate and infeasible candidates in
# Stata separately; R supplies the authoritative numeric value for each order.
for (s in c(3L, 5L)) {
  f <- clate_dnn(X = X, X0 = X0, Y = Y, D = D, A = A, e = e,
    m_y0 = my0, m_y1 = my1, m_d0 = md0, m_d1 = md1, clip = .05, s = s)
  emit(paste0("grid", s), rbind(f$theta, f$se))
}
writeLines(lines, "tests/fixtures/r_clate_fixtures.do")
